function startVisibleUpdates(statusElement) {
  let timerId;
  let ticks = 0;

  function stopUpdates() {
    if (timerId !== undefined) {
      window.clearInterval(timerId);
      timerId = undefined;
    }
  }

  function syncVisibility() {
    if (document.hidden) {
      stopUpdates();
      return;
    }
    if (timerId !== undefined) return;

    timerId = window.setInterval(() => {
      ticks += 1;
      statusElement.textContent = `Active updates: ${ticks}`;
    }, 1000);
  }

  document.addEventListener("visibilitychange", syncVisibility);
  syncVisibility();

  return () => {
    document.removeEventListener("visibilitychange", syncVisibility);
    stopUpdates();
  };
}

const statusElement = document.querySelector("#status");
if (statusElement) {
  const stopVisibleUpdates = startVisibleUpdates(statusElement);
  // Call stopVisibleUpdates when this feature is disposed.
}

